import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_includes_none_in_denominator():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_sessions():
    groups = {"a": [{"converted": True}], "b": [{"converted": False}] * 3, "c": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"c": []}) == 0.0


def test_window_counts_only_trailing_days():
    assert conversions_in_window([5, 2, 1], 0) == 0
    assert conversions_in_window([5, 2, 1], 2) == 3
    assert conversions_in_window([5, 2, 1], 4) == 8


def test_log_skips_blank_and_comment_lines_and_strips_fields():
    lines = ["", "  \t", "  # ignored", "  a , 2 , 0 ", " b, 3,   "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 2, "converted": False},
        {"id": "b", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,today,0"])
def test_log_error_reports_input_position(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["", "a,1,1", " # ignored", bad_line])


def test_duplicate_id_keeps_last_input_record_then_sorts():
    old = {"id": "a", "day": 9, "converted": False}
    new = {"id": "a", "day": 2, "converted": True}
    tied = {"id": "b", "day": 2, "converted": False}
    first = {"id": "c", "day": 1, "converted": True}
    assert dedupe_sessions([old, tied, first, new]) == [first, new, tied]


def test_daily_counts_respect_bounds_and_fill_gaps():
    events = [{"day": d, "converted": True} for d in (0, 1, 3, 3, 4)]
    assert daily_conversion_counts(events, 1, 3) == [1, 0, 2]
    assert daily_conversion_counts(events, 3, 1) == []


def test_summary_uses_calendar_days_and_only_nonempty_groups():
    events = [{"day": d, "converted": flag} for d, flag in [(1, True), (3, True), (5, False)]]
    assert campaign_summary({"a": events, "b": []}, 2) == {"rate": 0.667, "recent": 0, "groups": 1}
    assert campaign_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_rankings_and_rates():
    groups = {"z": [{"converted": False}], "empty": [], "b": [{"converted": True}], "a": [{"converted": True}]}
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 5) == ["a", "b", "z"]
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", 1.0), ("empty", None), ("z", 0.0)]


def test_streak_counts_consecutive_positive_days():
    assert longest_conversion_streak([1, 0, 2, 3, -1, 1]) == 2
    assert longest_conversion_streak([]) == 0
    assert longest_conversion_streak([0, -1]) == 0
